ALTER TABLE public.payments ADD COLUMN IF NOT EXISTS proof_file_path text, ADD COLUMN IF NOT EXISTS proof_file_name text;
ALTER TABLE public.payments ADD CONSTRAINT payment_proof_pair CHECK ((proof_file_path IS NULL AND proof_file_name IS NULL) OR (proof_file_path IS NOT NULL AND proof_file_name IS NOT NULL AND length(proof_file_name) BETWEEN 1 AND 255 AND proof_file_path ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/proof\.(jpg|png|webp|pdf)$'));
CREATE POLICY "Staff can read payment proofs" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'payment-proofs' AND public.is_staff(auth.uid()));
CREATE POLICY "Staff can upload own payment proofs" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'payment-proofs' AND public.is_staff(auth.uid()) AND owner_id = auth.uid()::text AND (storage.foldername(name))[1] = auth.uid()::text AND name ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/proof\.(jpg|png|webp|pdf)$' AND metadata->>'mimetype' IN ('image/jpeg','image/png','image/webp','application/pdf'));
CREATE POLICY "Owner or admin can delete payment proofs" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'payment-proofs' AND public.is_staff(auth.uid()) AND (owner_id = auth.uid()::text OR public.is_admin(auth.uid())));
